     1098:         /*
     1099:          * If one of the retrieved objects somehow generated an error,
     1100:          * we ignore it.  The check for NID_undef below will detect the
     1101:          * error and simply skip to the next NID.
     1102:          */
     1103:         ERR_clear_error();
     1104: 
     1105:         if (OBJ_obj2nid(obj) == NID_undef)
     1106:             continue;
     1107: 
     1108:         if ((n = OBJ_obj2txt(NULL, 0, obj, 1)) == 0) {
     1109:             BIO_printf(bio_out, "# None-OID object: %s, %s\n", sn, ln);
     1110:             continue;
     1111:         }
     1112:         if (n < 0)
     1113:             break; /* Error */
     1114: 
