     1116:             oid_buf = OPENSSL_realloc(oid_buf, n + 1);
     1117:             if (oid_buf == NULL) {
     1118:                 BIO_printf(bio_err, "ERROR: Memory allocation\n");
     1119:                 break; /* Error */
     1120:             }
     1121:             oid_size = n + 1;
     1122:         }
     1123:         if (OBJ_obj2txt(oid_buf, oid_size, obj, 1) < 0)
     1124:             break; /* Error */
>>>  1125:         if (ln == NULL || strcmp(sn, ln) == 0)
     1126:             BIO_printf(bio_out, "%s = %s\n", sn, oid_buf);
     1127:         else
     1128:             BIO_printf(bio_out, "%s = %s, %s\n", sn, ln, oid_buf);
     1129:     }
